options.afterRender:
// Shows the picture the camera took at the instant, read from Panoramax: the small copy (about 45 KB)
// while the instant moves, the large one (about 650 KB) once it has rested 800 ms. One picture loads at a
// time; while it loads, only the latest wanted waits, so a fast play skips pictures instead of queueing them.
const row = context.data || {};
context.element.style.height = '100%';
const box = context.element.querySelector('.ride-view');
const self = this;
if (!box || !row.photo) {
  return;
}
if (!self.img || self.box !== box || !self.img.isConnected) {
  self.box = box;
  self.img = document.createElement('img');
  self.img.alt = 'The picture the camera took';
  self.img.style.cssText = 'width:100%;height:100%;object-fit:contain;background:#000;display:block';
  box.replaceChildren(self.img);
  self.shown = null;
  self.loading = false;
  self.next = null;
  self.id = null;
}
if (self.id === row.picture_id) {
  return;
}
self.id = row.picture_id;
const show = (url) => {
  if (self.shown === url) {
    return;
  }
  if (self.loading) {
    self.next = url;
    return;
  }
  self.loading = true;
  const pre = new Image();
  pre.onload = pre.onerror = () => {
    self.loading = false;
    if (pre.naturalWidth) {
      self.img.src = url;
      self.shown = url;
    }
    const next = self.next;
    self.next = null;
    if (next) {
      show(next);
    }
  };
  pre.src = url;
};
clearTimeout(self.sharp);
show(row.thumb);
self.sharp = setTimeout(() => {
  if (self.id === row.picture_id) {
    show(row.photo);
  }
}, 800);

options.styles:
.ride { display: flex; flex-direction: column; height: 100%; gap: 6px; }
.ride-view { flex: 1; min-height: 0; background: #000; border-radius: 2px; overflow: hidden; }
.ride-caption { font-size: 12px; line-height: 1.4; color: #9AA5B1; }
.ride-caption a { color: inherit; text-decoration: underline; }
